// Synthetic training transcription: source type 10 -> catalog row TH14_SHARD (512).

const TIME_LIMIT: int = 1524;
const OPENING_BUFFER: int = 120;

const TH14_SHARD: int = 512;       // etSprite(0, 10, 6): native type 10, target row 512
const SHARD_COLOR: int = 6;
const SHARD_SPEED: fx = 2fx;       // etSpeed(0, 2.0, 0.2): one layer -> 2.0 only
const ACCEL_MAG: fx = 0.0333333fx; // etEx ACCEL r = 0.033333335, a = 120

// etEx(0, 0, 4, 120, -999999, 0.033333335, %F2 - 3.1415927):
// fixed-direction acceleration for 120 frames, then release.
xformdef ECIR_ACCEL(dir: angle, mag: fx) {
    @120 set_gravity(mag * cos(dir), mag * sin(dir));
    set_gravity(0fx, 0fx);
}

// ECir00_at (source 49-81). etAim(0, 1) is the fixed-direction fan mode:
// per-bullet angle = alpha + F(N, i); etAngle's second angle is the lane gap.
async sub ecir00_at(face: angle) {
    wait(10);
    var n: int = 1;                     // !E 1 / !N 3 / !H 5 / !LO 7
    var r: int = global(GVAR_RANK);
    if r == RANK_NORMAL { n = 3; }
    if r == RANK_HARD { n = 5; }
    if r >= RANK_LUNATIC { n = 7; }
    sh_reset(0);
    sh_sprite(0, TH14_SHARD, SHARD_COLOR);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, SHARD_SPEED, 0fx);
    sh_xform(0, ECIR_ACCEL(face - 180deg, ACCEL_MAG));
    sh_dist(0, -8fx);                   // ANIM entry: position -= 4 * velocity (speed 2)
    for i in 0..2 {                     // $B = $I0 = 2 salvos, 4 frames apart
        var u: fx = (rand(65536) - 32768) as fx / 32fx / 1024fx;              // RANDF2
        var alpha: angle = face + ((1820fx * u) as int as angle);       // +-10deg jitter
        sh_angle(0, alpha, 10deg);      // etAngle(0, %F2 + RANDF2*0.17453292, 0.17453292)
        sh_fire(0);
        wait(4);
    }
}

// ECir00 (source 14-47): fly in along the relative-position interpolation,
// fire the async helper, then drift at the player.
async sub ecir00(y0: fx, tx: fx, ty: fx, face: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);                  // setHurtbox(24, 24): radius 24 * 0.5
    set_hitbox(8fx);                    // setHitbox(16, 16): radius 16 * 0.5
    set_enemy_flag(ENEMY_NO_BODY, 1);   // flagSet(15) includes body-collision off (0x2)
    move_to(160, tx, y0 + ty, EASE_QUAD_IN);   // movePosRelTime(160, 1, F0, F1)
    wait(160);
    set_enemy_flag(ENEMY_NO_BODY, 0);   // flagClear(15)
    spawn ecir00_at(face);
    wait(120);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // moveVel(%ANGLE_PLAYER, 0.0)
    move_speed(120, 3fx, EASE_LINEAR);             // moveSpeedTime(120, 0, 3.0)
    loop { wait(1000); }                           // goto wait(1000) forever
}

// One enmCreate from MainSub01 (584-590, 596-602, 608-614).
// Random draws keep the source order: parent F1 first, then the child's
// movePosRel x and y offsets.
sub wave_one(y0: fx, tx: fx, f1_center: fx, face: angle) {
    var u1: fx = (rand(65536) - 32768) as fx / 32fx / 1024fx;
    var ty: fx = 32fx * u1 - f1_center;            // F1 = RANDF2*32 - 128/96/32
    var u2: fx = (rand(65536) - 32768) as fx / 32fx / 1024fx;
    var u3: fx = (rand(65536) - 32768) as fx / 32fx / 1024fx;
    var sx: fx = 160fx + 32fx * u2;                // movePosRel x = 160 + RANDF2*32
    var sy: fx = y0 + 64fx * u3;                   // movePosRel y = RANDF2*64
    _ = spawn_enemy(sx, sy, 160, 0, 1000, 0, ecir00(y0, tx, ty, face));
}

// MainSub01 580-615: three ECir00 batches, starts 0/68/136, schedule 206 frames.
async sub pattern() {
    wait(OPENING_BUFFER);
    var f0: fx = 160fx;
    for i1 in 0..6 {
        f0 = f0 - 32fx;
        wave_one(200fx, f0, 128fx, -90deg);
        wait(3);
    }
    wait(50);
    f0 = -160fx;
    for i2 in 0..6 {
        f0 = f0 + 32fx;
        wave_one(240fx, f0, 96fx, -90deg);
        wait(3);
    }
    wait(50);
    f0 = -160fx;
    var face: angle = -90deg;
    for i3 in 0..10 {
        f0 = f0 + 32fx;
        wave_one(280fx, f0, 32fx, face);
        face = 0deg - face;            // F2 = F2 * -1 per creation
        wait(7);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
